107	#[inline]
108	fn parse_root_operation_type_definition(p: &mut GraphqlParser) -> ParsedSyntax {
109	    if !(is_at_root_operation_type_definition(p)) {
110	        return Absent;
111	    }
112	    let m = p.start();
113	    if p.at_ts(OPERATION_TYPE) {
114	        let m = p.start();
115	        p.bump_ts(OPERATION_TYPE);
116	        m.complete(p, GRAPHQL_OPERATION_TYPE);
117	    }
118	    // missing operation type
119	    else if p.at(T![:]) {
120	        p.error(expected_operation_type(p, p.cur_range()));
121	    }
122	    // handle typo in operation type
123	    else {
124	        p.error(expected_operation_type(p, p.cur_range()));
125	        p.bump_any();
126	    }
127	    p.expect(T![:]);
128	    parse_named_type(p).or_add_diagnostic(p, expected_named_type);
129	
130	    Present(m.complete(p, GRAPHQL_ROOT_OPERATION_TYPE_DEFINITION))
131	}
