133	#[inline]
134	fn is_at_root_operation_types(p: &mut GraphqlParser<'_>) -> bool {
135	    p.at(T!['{'])
136	        // Must have a colon to be recognized as a root operation type definition
137	        // else it's likely a new operation definition
138	        || (p.at_ts(OPERATION_TYPE) && p.nth_at(1, T![:]))
139	}
140	
141	#[inline]
142	fn is_at_root_operation_type_definition(p: &mut GraphqlParser<'_>) -> bool {
143	    p.at_ts(OPERATION_TYPE)
144	        // missing operation type
145	        || p.at(T![:])
146	        // there is likely a typo in the operation type
147	        || p.nth_at(1, T![:])
148	}
149	
150	/// To prevent a missing closing brace from causing the parser to include the next definition
151	/// as part of the root operation type definition
152	/// ```graphql
153	/// schema {
154	///    query: Query
155	///    mutation: Mutation
156	///
157	/// schema {
158	///   query: Query
159	/// }
160	#[inline]
161	fn is_at_root_operation_type_definition_end(p: &mut GraphqlParser<'_>) -> bool {
162	    // stop at closing brace or at the start of a new definition
163	    p.at(T!['}'])
164	        || (!p.at_ts(OPERATION_TYPE) && is_at_definition(p))
165	        // start of a new operation definition
166	        || (p.at_ts(OPERATION_TYPE) && !p.nth_at(1, T![:]))
167	}
